//! Berlin SPARQL Benchmark ("explore" use case) query benchmarks over HDT.
//!
//! This is the Rust equivalent of Comunica's `performance/benchmark-bsbm-hdt`.
//! The data is generated by the official `bsbmtools` generator; the queries are
//! the official twelve explore templates with parameters substituted from the
//! generated graph (see `scripts/gen-bsbm-data.py` for why the official test
//! driver is not used).
//!
//! BSBM complements `WatDiv` rather than repeating it. `WatDiv` is pure basic
//! graph patterns; BSBM's twelve templates bring `OPTIONAL`, `UNION`, `FILTER`
//! with regex and date comparison, `ORDER BY`/`LIMIT`/`OFFSET`, `DESCRIBE` and
//! `CONSTRUCT`. Improvements aimed at pattern evaluation should move both;
//! anything that moves only one is worth a second look.
//!
//! Fixtures come from `make bench-bsbm` (or
//! `scripts/gen-bsbm-data.py <product-count>`). The HDT package is built here
//! on first run from the generated N-Triples, since the generator does not
//! produce one. Without the fixtures this target prints how to get them and
//! measures nothing, so `cargo bench` still works on a fresh clone.
//!
//! Product count is `DE_BSBM_PRODUCT_COUNT`: `1000` (~372K triples, the
//! default) or `10000` (~3.5M triples). Comunica runs both, as
//! `benchmark-bsbm-hdt` and `benchmark-bsbm-hdt-10k`.

mod common;

use common::{benches_dir, null_writer, parse_instances, run_instances};
use criterion::{Criterion, criterion_group, criterion_main};
use de::create;
use de::query::DeOutput;
use de::sparql::AggregateHdt;
#[cfg(target_os = "linux")]
use pprof::criterion::{Output, PProfProfiler};
use spargebra::Query;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::time::Duration;

const PRODUCT_COUNT_VAR: &str = "DE_BSBM_PRODUCT_COUNT";
const DEFAULT_PRODUCT_COUNT: &str = "1000";

fn fixture_dir(product_count: &str) -> PathBuf {
    benches_dir().join("bsbm").join(product_count)
}

/// One template's five instances, with the serialiser its result form needs.
struct Template {
    name: String,
    out: DeOutput,
    queries: Vec<Query>,
}

/// Read `queries/manifest.tsv` and group its rows back into templates.
///
/// The manifest names each instance `q<NN>_<i>` and records whether the
/// template is a `SELECT` (tabular) or a `DESCRIBE`/`CONSTRUCT` (a graph), which
/// decides the output format. Grouping is by the `q<NN>` prefix, and a
/// `BTreeMap` keeps the twelve templates in numeric order in the report.
fn load_workload(queries_dir: &Path) -> Vec<Template> {
    let manifest_path = queries_dir.join("manifest.tsv");
    let manifest = std::fs::read_to_string(&manifest_path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", manifest_path.display()));

    let mut grouped: BTreeMap<String, (DeOutput, Vec<String>)> = BTreeMap::new();
    for line in manifest.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let mut fields = line.split('\t');
        let (Some(name), Some(file), Some(form)) = (fields.next(), fields.next(), fields.next())
        else {
            panic!(
                "malformed manifest row in {}: {line}",
                manifest_path.display()
            );
        };
        let out = match form {
            "select" => DeOutput::CSV,
            "graph" => DeOutput::TURTLE,
            other => panic!(
                "unknown result form {other:?} in {}",
                manifest_path.display()
            ),
        };
        let template = name
            .split_once('_')
            .map_or(name, |(prefix, _instance)| prefix)
            .to_string();
        let path = queries_dir.join(file);
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
        grouped
            .entry(template)
            .or_insert((out, Vec::new()))
            .1
            .push(text);
    }

    grouped
        .into_iter()
        .map(|(name, (out, texts))| Template {
            queries: parse_instances(&name, &texts),
            name,
            out,
        })
        .collect()
}

/// Build the HDT package from the generated N-Triples if it is not there yet.
///
/// `bsbmtools` emits RDF, not HDT, and the package is a deterministic function
/// of that RDF, so building it once on first run keeps the fixture script free
/// of any dependency on a built `de` binary.
fn ensure_hdt(runtime: &tokio::runtime::Runtime, dir: &Path) -> String {
    let hdt = dir.join("dataset.hdt");
    let hdt_path = hdt
        .to_str()
        .expect("BSBM fixture path must be valid UTF-8")
        .to_string();
    if hdt.exists() {
        return hdt_path;
    }
    let nt = dir.join("dataset.nt");
    let sources = vec![
        nt.to_str()
            .expect("BSBM fixture path must be valid UTF-8")
            .to_string(),
    ];
    eprintln!("building {} from dataset.nt (one-off)", hdt.display());
    runtime.block_on(async {
        create::do_create(&hdt_path, &sources)
            .await
            .expect("failed to build the BSBM HDT package");
    });
    hdt_path
}

fn bsbm(c: &mut Criterion) {
    let product_count =
        std::env::var(PRODUCT_COUNT_VAR).unwrap_or_else(|_| DEFAULT_PRODUCT_COUNT.to_string());
    let dir = fixture_dir(&product_count);
    let nt = dir.join("dataset.nt");
    let queries_dir = dir.join("queries");

    let manifest = queries_dir.join("manifest.tsv");
    if !nt.exists() || !manifest.exists() {
        let missing = if nt.exists() { &manifest } else { &nt };
        eprintln!(
            "skipping BSBM benchmarks: {} is missing.\n\
             run `make bench-bsbm` (or `BSBM_PRODUCT_COUNT={product_count} make bench-bsbm`) to \
             generate the fixtures.",
            missing.display(),
        );
        return;
    }

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("failed to build tokio runtime");
    let hdt_path = ensure_hdt(&runtime, &dir);

    let store = AggregateHdt::new(std::slice::from_ref(&hdt_path))
        .expect("failed to register the BSBM HDT package");

    // One untimed open, so that building the `.index.v5-rust-cache` sidecar and
    // faulting the package in do not land on the first measured group.
    drop(
        store
            .get_snapshot(None)
            .expect("failed to warm the BSBM HDT index"),
    );

    bench_open(c, &product_count, &store);

    let snapshot = store
        .get_snapshot(None)
        .expect("failed to open the BSBM HDT package");
    let workload = load_workload(&queries_dir);

    let mut group = c.benchmark_group(format!("bsbm_query/{product_count}"));
    group.sample_size(10);
    group.measurement_time(Duration::from_secs(10));
    for template in &workload {
        group.bench_function(&template.name, |b| {
            let mut writer = null_writer();
            b.iter(|| {
                run_instances(
                    &template.name,
                    &template.queries,
                    &snapshot,
                    &template.out,
                    &mut writer,
                );
            });
        });
    }
    group.finish();
}

/// Time `get_snapshot` on its own; see `benches/watdiv.rs` for why.
fn bench_open(c: &mut Criterion, product_count: &str, store: &AggregateHdt) {
    let mut group = c.benchmark_group(format!("bsbm_open/{product_count}"));
    group.sample_size(10);
    group.measurement_time(Duration::from_secs(10));
    group.bench_function("get_snapshot", |b| {
        b.iter(|| {
            drop(
                store
                    .get_snapshot(None)
                    .expect("failed to open the BSBM HDT package"),
            );
        });
    });
    group.finish();
}

#[cfg(target_os = "linux")]
criterion_group! {
    name = benches;
    config = Criterion::default()
        .with_profiler(PProfProfiler::new(100, Output::Protobuf))
        .warm_up_time(Duration::from_millis(500));
    targets = bsbm
}

#[cfg(not(target_os = "linux"))]
criterion_group! {
    name = benches;
    config = Criterion::default().warm_up_time(Duration::from_millis(500));
    targets = bsbm
}

criterion_main!(benches);
